"""Generated by the NL to Flow Diagram Encoder Pipeline."""

numvar = 0

givenNum = 0

numlist = []

loop = True

while (loop == True):
    givenNum = input('Enter Number: ')
    try:
        givenNum = int(givenNum)
        loop = False
    except Exception:
        print("That's Not a Valid Number, Please Try Again!")

while (numvar <= givenNum):
    numvar = (numvar + 1)
    if ((givenNum % numvar) == 0):
        numlist.append(numvar)

while (loop == False):
    try:
        x = numlist.pop(0)
        print(f'{x} is a Divisor of {givenNum}')
    except Exception:
        raise SystemExit
